module fsm (
        input clk,
        input reset,
        input f,
        output reg y);parameter R0=0, R1=1, R2=2;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= R0;
		else 
			state <= next;


	always_comb begin
		case(state)
			R0: next = f ? R2 : R1;
			R1: next = f ? R0 : R2;
			R2: next = f ? R0 : R1;
			default: next = 'x;
		endcase
	end

	assign y = (state == R0 || state == R2);

endmodule

