module top_module(
  input clk_in,
  input reset,
  input [7:0] divisor,
  output reg clk_out,
  output reg locked
);reg [3:0] counter;
  reg [3:0] stable_counter;
  reg locked_temp;

  always @(posedge clk_in or posedge reset) begin
    if (reset) begin
      counter <= 4'b0;
      clk_out <= 1'b0;
      stable_counter <= 4'b0;
      locked_temp <= 1'b0;
      locked <= 1'b0;
    end else begin
      counter <= counter + 1;
      if (counter >= divisor) begin
        counter <= 4'b0;
        clk_out <= ~clk_out;
      end
      if (stable_counter >= 4'b1010) begin
        locked_temp <= 1'b1;
      end else begin
        locked_temp <= 1'b0;
      end
      if (locked_temp == 1'b1 && clk_out == 1'b1) begin
        stable_counter <= 4'b0;
        locked <= 1'b1;
      end else begin
        stable_counter <= stable_counter + 1;
        locked <= 1'b0;
      end
    end
  end

endmodule

