description:
Design a frequency divider circuit that reduces the input clock frequency by a factor of three. The module accepts an input clock signal (`clk_in`) and a negative reset signal (`nreset`). It counts rising edges of the input clock to detect when two cycles have been completed. Additionally, it counts falling edges to synchronize with those transitions. The output clock signal (`clk_out`) is generated to be high during the intervals when neither counter has reached a count of two, effectively toggling the output every three input clock cycles. This design can be used in applications requiring clock signal reduction for timing adjustments in digital systems.
module top_module(
    clk_in,        
    nreset,        
    clk_out        
  );

code:
module top_module(
    clk_in,        
    nreset,        
    clk_out        
  );input clk_in, nreset;


  output clk_out;

  reg [1:0] pos_count, neg_count;


  always@(posedge clk_in)begin
    if (~nreset)begin
      pos_count<=0;
    end
    else if(pos_count == 2)begin
      pos_count <=0;
    end
    else begin
      pos_count<=pos_count+1;
    end
  end


  always@(negedge clk_in)begin
    if (~nreset)begin
      neg_count<=0;
    end
    else if(neg_count == 2)begin
      neg_count <=0;
    end
    else begin
      neg_count<=neg_count+1;
    end
  end   



  assign clk_out = ((pos_count!=2) && (neg_count!=2));

endmodule

