module top_module(
  clk,
  rst,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  data_count,
  prog_full
);input clk;
input rst;
input [15 : 0] din;
input wr_en;
input rd_en;
output reg [15 : 0] dout; // Changed output to reg
output full;
output empty;
output [12 : 0] data_count;
output prog_full;

reg [15:0] mem[0:8191];
reg [12:0] wr_ptr = 0;
reg [12:0] rd_ptr = 0;
reg [12:0] cnt = 0;
reg full_reg = 0;
reg empty_reg = 1;

integer i;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    wr_ptr <= 0;
    rd_ptr <= 0;
    cnt <= 0;
    full_reg <= 0;
    empty_reg <= 1;
    for (i=0; i<8192; i=i+1) begin
      mem[i] <= 0;
    end
  end else begin
    if (wr_en && !full_reg) begin
      mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      cnt <= cnt + 1;
      if (wr_ptr == 8191) begin // Changed condition to 8191 (array is 0-indexed)
        wr_ptr <= 0;
      end
      if (cnt == 8192) begin
        full_reg <= 1;
      end
      empty_reg <= 0;
    end
    if (rd_en && !empty_reg) begin
      dout <= mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      cnt <= cnt - 1;
      if (rd_ptr == 8191) begin // Changed condition to 8191 (array is 0-indexed)
        rd_ptr <= 0;
      end
      if (cnt == 1) begin
        empty_reg <= 1;
      end
      full_reg <= 0;
    end
  end
end

assign full = full_reg;
assign empty = empty_reg;
assign data_count = cnt;

endmodule

