description:
Design a binary divider module that toggles its output based on the specified divisors (5 and 2) when a clock signal is present. On each positive clock edge, the module increments a counter until it reaches either of the defined divisor values. The output state changes when the counter meets these conditions, effectively creating a divide-by-5 and divide-by-2 behavior combined. A reset input is implemented to initialize the counter and output state, allowing the module to be reset to a known state.
module top_module(
reset,
out,
clk
);

code:
module top_module(
reset,
out,
clk
);output out;
input clk;
input reset;

parameter divisor1 = 5;
parameter divisor2 = 2;

reg[31:0] cnt1;
reg result;
wire EN;
wire compare1,compare2;



always@(posedge clk or negedge reset)
begin
   if(reset == 0)
      cnt1 <= 0;
	else if(cnt1 == divisor1)
		cnt1 <= 1;
	else
		cnt1 <= cnt1 + 1;
end


assign compare1 = (cnt1 == 5) ? 1 : 0;


assign compare2 = (cnt1 == divisor2) ? 1 : 0;

assign EN = compare1 | compare2;



always@(posedge clk or negedge reset)
begin
	if(reset == 0)
		result <= 0;
	else if(EN) 
	result <= !result;

end

assign out = result;
endmodule

