module counter_3bit_updown (
    input wire clk,
    input wire reset,
    input wire up_down,
    output reg [2:0] count
);

    always @(posedge clk) begin
        if (reset)
            count <= 3'b000;
        else if (up_down)
            count <= count + 1;
        else
            count <= count - 1;
    end

