module top_module(input clk, input [7:0] adc_d, input [7:0] threshold,
	output [7:0] min, output [7:0] max);reg [7:0] min_val = 255;
	reg [7:0] max_val = 0;
	reg [7:0] cur_min_val = 255;
	reg [7:0] cur_max_val = 0;
	reg [1:0] state = 0;

	always @(posedge clk)
	begin
		case (state)
		0: 
			begin
				if (cur_max_val >= ({1'b0, adc_d} + threshold))
					state <= 2;
				else if (adc_d >= ({1'b0, cur_min_val} + threshold))
					state <= 1;
				if (cur_max_val <= adc_d)
					cur_max_val <= adc_d;
				else if (adc_d <= cur_min_val)
					cur_min_val <= adc_d;					
			end
		1: 
			begin
				if (cur_max_val <= adc_d)
					cur_max_val <= adc_d;
				else if (({1'b0, adc_d} + threshold) <= cur_max_val) begin
					state <= 2;
					cur_min_val <= adc_d;
					max_val <= cur_max_val;
				end
			end
		2: 
			begin
				if (adc_d <= cur_min_val)
					cur_min_val <= adc_d;					
				else if (adc_d >= ({1'b0, cur_min_val} + threshold)) begin
					state <= 1;
					cur_max_val <= adc_d;
					min_val <= cur_min_val;
				end
			end
		endcase
	end

	assign min = min_val;
	assign max = max_val;

endmodule

module top_module(
		r,g,b,
		current_x,current_y,request,
		vga_r,vga_g,vga_b,vga_hs,vga_vs,vga_blank,vga_clock,
		clk27,rst27);input [9:0]	r,g,b;
output [9:0] current_x;
output [9:0] current_y;
output request;

output [9:0] vga_r, vga_g, vga_b;
output vga_hs, vga_vs, vga_blank, vga_clock;

input clk27, rst27;




parameter	H_FRONT	=	16; 
parameter	H_SYNC	=	96; 
parameter	H_BACK	=	48; 
parameter	H_ACT	=	640;
parameter	H_BLANK	=	H_FRONT+H_SYNC+H_BACK;
parameter	H_TOTAL	=	H_FRONT+H_SYNC+H_BACK+H_ACT;


parameter	V_FRONT	=	11;
parameter	V_SYNC	=	2;
parameter	V_BACK	=	31;
parameter	V_ACT	=	480;
parameter	V_BLANK	=	V_FRONT+V_SYNC+V_BACK;
parameter	V_TOTAL	=	V_FRONT+V_SYNC+V_BACK+V_ACT;



reg [9:0] h_cntr, v_cntr, current_x, current_y;
reg h_active, v_active, vga_hs, vga_vs;

assign	vga_blank = h_active & v_active;
assign	vga_clock = ~clk27;
assign	vga_r = r;
assign	vga_g = g;
assign	vga_b = b;
assign	request	= ((h_cntr>=H_BLANK && h_cntr<H_TOTAL)	&&
						 (v_cntr>=V_BLANK && v_cntr<V_TOTAL));

always @(posedge clk27) begin
	if(rst27) begin
		h_cntr <= 0;
		v_cntr <= 0;
		vga_hs <= 1'b1;
		vga_vs <= 1'b1;
		current_x <= 0;
		current_y <= 0;
		h_active <= 1'b0;
		v_active <= 1'b0;
	end
	else begin
		if(h_cntr != H_TOTAL) begin
			h_cntr <= h_cntr + 1'b1;
			if (h_active) current_x <= current_x + 1'b1;
			if (h_cntr == H_BLANK-1) h_active <= 1'b1;
		end
		else begin
			h_cntr	<= 0;
			h_active <= 1'b0;
			current_x <= 0;
		end

		if(h_cntr == H_FRONT-1) begin
			vga_hs <= 1'b0;
		end

		if (h_cntr == H_FRONT+H_SYNC-1) begin
			vga_hs <= 1'b1;

			if(v_cntr != V_TOTAL) begin
				v_cntr <= v_cntr + 1'b1;
				if (v_active) current_y <= current_y + 1'b1;
				if (v_cntr == V_BLANK-1) v_active <= 1'b1;
			end
			else begin
				v_cntr <= 0;
				current_y <= 0;
				v_active <= 1'b0;
			end
			if(v_cntr == V_FRONT-1) vga_vs <= 1'b0;
			if(v_cntr == V_FRONT+V_SYNC-1) vga_vs <= 1'b1;
		end
	end
end

endmodule

description:
Design a 3-bit toggle flip-flop (TFF) circuit that changes the state of its output whenever the corresponding button input is pressed. The circuit uses a system clock as the trigger for state changes and has an active-low reset functionality controlled by the fourth button. The current state of the TFF is represented by a 3-bit register, and the outputs are reflected on a 4-bit LED display. When a button is detected in a pressed state, the flip-flop toggles its corresponding output bit. The circuit captures the button state transitions using two registered signals to filter out noise.
module top_module(
    input sysclk, 
    input [3:0] btn,
    output [3:0] led
    );

code:
module top_module(
    input sysclk, 
    input [3:0] btn,
    output [3:0] led
    );wire [2:0] T;
    reg [2:0] btnC, btnD, Q;
    reg resetD; 
    wire reset = btn[3], clk = sysclk;

    assign led =  {resetD, Q};
    assign T = btnC & (~btnD); 

    always @(posedge clk) begin
        btnC <= btn;        
        btnD <= btnC;       
        resetD <= btn[3];   
    end

    always @(posedge clk) begin 
        if (reset == 1'b1)
            Q[2:0] <= 3'b000;
        else begin
            if (T[2] == 1'b1)
                Q[2] <= ~led[2];
            if (T[1] == 1'b1)
                Q[1] <= ~led[1];
            if (T[0] == 1'b1)
                Q[0] <= ~led[0];
        end
    end
endmodule

