module top_module(clk, rst, clr, din, we, dout, re, full, empty);parameter dw = 8;

input		clk, rst;
input		clr;
input   [dw:1]	din;
input		we;
output  [dw:1]	dout;
input		re;
output		full, empty;

reg [dw-1:0] mem [3:0];
reg [1:0] wp, rp;
wire [1:0] wp_p1, wp_p2, rp_p1;
reg gb = 0;

assign wp_p1 = wp + 2'h1;
assign wp_p2 = wp + 2'h2;
assign rp_p1 = rp + 2'h1;

always @(posedge clk or negedge rst) begin
    if(!rst) wp <= #1 2'h0;
    else if(clr) wp <= #1 2'h0;
    else if(we) wp <= #1 wp_p1;
end

always @(posedge clk or negedge rst) begin
    if(!rst) rp <= #1 2'h0;
    else if(clr) rp <= #1 2'h0;
    else if(re) rp <= #1 rp_p1;
end

always @(posedge clk) begin
    if(we) mem[wp] <= #1 din;
end

assign dout = mem[rp];

always @(posedge clk) begin
    if(!rst) gb <= #1 1'b0;
    else if(clr) gb <= #1 1'b0;
    else if((wp_p1 == rp) & we) gb <= #1 1'b1;
    else if(re) gb <= #1 1'b0;
end

assign full = (wp == rp) & gb;
assign empty = (wp == rp) & ~gb;

endmodule

