module d_flip_flop(clk, reset, d, q);

    input clk;
    input reset;
    input d;
    output q;
    reg q;

    always @(posedge clk or posedge reset)
        begin
            if (reset)
                q <= 0;
            else
                q <= d;
        end

endmodule

