module top_module(
    input wire [3:0] invec,
    output wire [2:0] outvec,
    output wire inv3,
    output wire inv2,
    output wire inv1,
    output wire inv0
);assign outvec[2] = invec[3];
assign outvec[1] = invec[2];
assign outvec[0] = invec[1] ^ invec[0];

assign inv3 = ~invec[3];
assign inv2 = ~invec[2];
assign inv1 = ~invec[1];
assign inv0 = ~invec[0];

endmodule

module fsm (
	input clk,
	input reset,
	input c,
	input d,
	output reg p);

	parameter M=0, N=1, O1=2, O2=3, O3=4;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= M;
		else state <= next;
	end

	always_comb begin
		case (state)
			M: next = c ? N : M;
			N: next = d ? O1 : O2;
			O1: next = d ? O2 : O3;
			O2: next = d ? O3 : M;
			O3: next = c ? N : M;
			default: next = 'x;
		endcase
	end

	assign p = (state == O2 && d);

endmodule

