    if ( reset ) 
      cnt <= 0; 
    else 
      cnt <= cnt + 1;

  always @ ( posedge clockMod4 or posedge reset )
    if ( reset ) 
      outClk <= 0; 
    else 
      outClk <= ~outClk;

endmodule

